def drop(xs, n):
  switch n:
    case 0:
      return xs
    case _:
      match xs:
        case List/Nil:
          return []
        case List/Cons:
          return drop(xs.tail, n - 1)

def maximum(xs, best):
  match xs:
    case List/Nil:
      return best
    case List/Cons:
      if xs.head > best:
        return maximum(xs.tail, xs.head)
      else:
        return maximum(xs.tail, best)
