  return keep_under_50(collapsed)

def collapse(xs):
  match xs:
    case List/Nil:
      return []
    case List/Cons:
      match xs.tail:
        case List/Nil:
          return [xs.head]
        case List/Cons:
          if xs.head == xs.tail.head:
            return collapse(xs.tail)
          else:
            return List/Cons(xs.head, collapse(xs.tail))

def keep_under_50(xs):
  match xs:
    case List/Nil:
      return []
    case List/Cons:
      rest = keep_under_50(xs.tail)
      if xs.head < 50:
        return List/Cons(xs.head, rest)
      else:
        return rest
